  // src/Utils/QuadTree.js
  var QuadTree = class _QuadTree {
    /**
     * @param {object} bounds { x, y, w, h } 区域（世界坐标，左上角）
     * @param {number} maxObjects 单节点最大对象数
     * @param {number} maxLevels 最大深度
     * @param {number} level 当前层级
     */
    constructor(bounds, maxObjects = 8, maxLevels = 6, level = 0) {
      this.bounds = bounds;
      this.maxObjects = maxObjects;
      this.maxLevels = maxLevels;
      this.level = level;
      this.objects = [];
      this.nodes = null;
    }
    clear() {
      this.objects.length = 0;
      if (this.nodes) {
        for (let i = 0; i < 4; i++) this.nodes[i].clear();
      }
    }
    reset(bounds) {
      this.bounds = bounds;
      this.objects.length = 0;
      this.nodes = null;
    }
    _split() {
      const { x, y, w, h } = this.bounds;
      const hw = w / 2;
      const hh = h / 2;
      const nl = this.level + 1;
      this.nodes = [
        new _QuadTree({ x: x + hw, y, w: hw, h: hh }, this.maxObjects, this.maxLevels, nl),
        new _QuadTree({ x, y, w: hw, h: hh }, this.maxObjects, this.maxLevels, nl),
        new _QuadTree({ x, y: y + hh, w: hw, h: hh }, this.maxObjects, this.maxLevels, nl),
        new _QuadTree({ x: x + hw, y: y + hh, w: hw, h: hh }, this.maxObjects, this.maxLevels, nl)
      ];
    }
    /** 判断对象（中心+半径）属于哪个象限，返回索引；跨界返回 -1 */
    _getIndex(obj) {
      const { x, y, w, h } = this.bounds;
      const midX = x + w / 2;
      const midY = y + h / 2;
      const r = obj.radius || 0;
      const top = obj.y + r < midY;
      const bottom = obj.y - r > midY;
      const left = obj.x + r < midX;
      const right = obj.x - r > midX;
      if (right) {
        if (top) return 0;
        if (bottom) return 3;
      } else if (left) {
        if (top) return 1;
        if (bottom) return 2;
      }
      return -1;
    }
    insert(obj) {
      if (this.nodes) {
        const index = this._getIndex(obj);
        if (index !== -1) {
          this.nodes[index].insert(obj);
          return;
        }
      }
      this.objects.push(obj);
      if (this.objects.length > this.maxObjects && this.level < this.maxLevels) {
        if (!this.nodes) this._split();
        let i = 0;
        while (i < this.objects.length) {
          const index = this._getIndex(this.objects[i]);
          if (index !== -1) {
            this.nodes[index].insert(this.objects.splice(i, 1)[0]);
          } else {
            i++;
          }
        }
      }
    }
    /**
     * 查询与给定区域（中心 cx,cy 半径 r）可能相交的对象，push 到 out 数组。
     */
    retrieve(cx, cy, r, out) {
      if (this.nodes) {
        const { x, y, w, h } = this.bounds;
        const midX = x + w / 2;
        const midY = y + h / 2;
        const top = cy - r < midY;
        const bottom = cy + r > midY;
        const left = cx - r < midX;
        const right = cx + r > midX;
        if (top) {
          if (right) this.nodes[0].retrieve(cx, cy, r, out);
          if (left) this.nodes[1].retrieve(cx, cy, r, out);
        }
        if (bottom) {
          if (left) this.nodes[2].retrieve(cx, cy, r, out);
          if (right) this.nodes[3].retrieve(cx, cy, r, out);
        }
      }
      const objs = this.objects;
      for (let i = 0; i < objs.length; i++) out.push(objs[i]);
      return out;
    }
    /** 调试：收集所有节点边界 */
    collectBounds(out) {
      out.push(this.bounds);
      if (this.nodes) {
        for (let i = 0; i < 4; i++) this.nodes[i].collectBounds(out);
      }
      return out;
    }
  };
  var QuadTree_default = QuadTree;

  // src/Utils/CollisionSystem.js
  var CollisionSystem = class {
    constructor() {
      this.tree = new QuadTree_default(
        { x: 0, y: 0, w: 1, h: 1 },
        GameConfig_default.performance.quadMaxObjects,
        GameConfig_default.performance.quadMaxLevels
      );
      this._queryBuffer = [];
    }
    /** 每帧重建：以玩家为中心的区域 */
    rebuild(player, enemies) {
      const span = GameConfig_default.spawn.ringMax * 3;
      this.tree.reset({
        x: player.x - span,
        y: player.y - span,
        w: span * 2,
        h: span * 2
      });
      for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i];
        if (e.active) this.tree.insert(e);
      }
    }
    /**
     * 查询圆形范围内的敌人，结果写入 out 数组（清空后填充）。
     */
    queryCircle(cx, cy, radius, out) {
      out.length = 0;
      this._queryBuffer.length = 0;
      this.tree.retrieve(cx, cy, radius, this._queryBuffer);
      for (let i = 0; i < this._queryBuffer.length; i++) {
        const e = this._queryBuffer[i];
        if (!e.active) continue;
        const rr = radius + e.radius;
        if (dist2(cx, cy, e.x, e.y) <= rr * rr) {
          out.push(e);
        }
      }
      return out;
    }
    /**
     * 查询距离 (cx,cy) 最近的敌人（在 maxRange 内）。可传 exclude Set 排除。
     */
    nearest(cx, cy, maxRange, exclude) {
      this._queryBuffer.length = 0;
      this.tree.retrieve(cx, cy, maxRange, this._queryBuffer);
      let best = null;
      let bestD2 = maxRange * maxRange;
      for (let i = 0; i < this._queryBuffer.length; i++) {
        const e = this._queryBuffer[i];
        if (!e.active) continue;
        if (exclude && exclude.has(e)) continue;
        const d2 = dist2(cx, cy, e.x, e.y);
        if (d2 < bestD2) {
          bestD2 = d2;
          best = e;
        }
      }
      return best;
    }
    /** 调试：可视化四叉树 */
    debugRender(ctx, camera) {
      const bounds = this.tree.collectBounds([]);
      ctx.save();
      ctx.strokeStyle = "rgba(80,200,255,0.25)";
      ctx.lineWidth = 1;
      for (let i = 0; i < bounds.length; i++) {
        const b = bounds[i];
        ctx.strokeRect(
          camera.worldToScreenX(b.x),
          camera.worldToScreenY(b.y),
          b.w,
          b.h
        );
      }
      ctx.restore();
    }
  };
  var CollisionSystem_default = CollisionSystem;

  // src/Player/Stats.js
  var Stats = class {
    constructor(base) {
      this.base = base;
      this.mods = {
        maxHpAdd: 0,
        regenAdd: 0,
        critRate: 0,
        critDmg: 0,
        lifesteal: 0,
        damageMul: 0,
        // 以 0 为基准，final = base * (1 + damageMul)
        moveSpeedMul: 0,
        atkSpeedMul: 0,
        pickupMul: 0
      };
      this.final = {};
      this.recompute();
    }
    addStat(stat, amount) {
      if (this.mods[stat] === void 0) {
        this.mods[stat] = 0;
      }
      this.mods[stat] += amount;
      this.recompute();
    }
    recompute() {
      const b = this.base;
      const m = this.mods;
      const f = this.final;
      f.maxHp = b.maxHp + m.maxHpAdd;
      f.regen = b.regen + m.regenAdd;
      f.critRate = Math.min(0.95, b.critRate + m.critRate);
      f.critDmg = b.critDmg + m.critDmg;
      f.lifesteal = b.lifesteal + m.lifesteal;
      f.damageMul = 1 + m.damageMul;
      f.moveSpeed = b.moveSpeed * (1 + m.moveSpeedMul);
      f.atkSpeedMul = 1 + m.atkSpeedMul;
      f.pickupRadius = b.pickupRadius * (1 + m.pickupMul);
      f.radius = b.radius;
      return f;
    }
  };
  var Stats_default = Stats;

