      ctx.save();
      ctx.translate(sx, sy + bobY);
      ctx.beginPath();
      ctx.ellipse(0, r * 0.9, r * 0.9, r * 0.35, 0, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(0,0,0,0.35)";
