  // src/Utils/ObjectPool.js
  var ObjectPool = class {
    constructor(factory, resetFn = null, initialSize = 0) {
      this._factory = factory;
      this._reset = resetFn;
      this._free = [];
      for (let i = 0; i < initialSize; i++) {
        this._free.push(this._factory());
      }
    }
    acquire() {
      let obj;
      if (this._free.length > 0) {
        obj = this._free.pop();
      } else {
        obj = this._factory();
      }
      obj.__pooled = false;
      return obj;
    }
    release(obj) {
      if (obj.__pooled) return;
      obj.__pooled = true;
      if (this._reset) this._reset(obj);
      this._free.push(obj);
    }
    get freeCount() {
      return this._free.length;
    }
  };
  var ObjectPool_default = ObjectPool;

