    ctx.fill();
    ctx.strokeStyle = "#3a1a1a";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-r * 0.3, r * 0.35 + wob);
    ctx.lineTo(r * 0.3, r * 0.35 + wob);
